const FALLBACK_GENRE = 'fantasy';
const unique = (items) => [...new Set(items)];

/** Names contributed to Character Creator's genre-agnostic random-name button. */
const CHARACTER_CREATOR_NAME_ADDITIONS = Object.freeze({
    firstNames: Object.freeze(unique(Object.values(CHARACTER_NAME_POOLS).flatMap(pool => pool.firstNames))),
    surnames: Object.freeze(unique(Object.values(CHARACTER_NAME_POOLS).flatMap(pool => pool.surnames))),
});

/** @returns {number} a value in [0, 1) */
function secureRandom() {
    if (globalThis.crypto?.getRandomValues) {
        const values = new Uint32Array(1);
        globalThis.crypto.getRandomValues(values);
        return values[0] / 0x100000000;
    }
    return Math.random();
}

/**
 * Choose a first-name / surname combination from one genre pool.
 * @param {string} genre
 * @param {() => number} [random]
 * @returns {string}
 */
function pickGenreCharacterName(genre, random = secureRandom) {
    const pool = CHARACTER_NAME_POOLS[genre] || CHARACTER_NAME_POOLS[FALLBACK_GENRE];
    const first = pool.firstNames[Math.min(pool.firstNames.length - 1, Math.floor(random() * pool.firstNames.length))];
    const surname = pool.surnames[Math.min(pool.surnames.length - 1, Math.floor(random() * pool.surnames.length))];
    return `${first} ${surname}`;
}

// ── src/features/character-creator/presets.js: /** @param {unknown} name */ ──
/** @param {unknown} name */
function normalizeCharacterCreatorPresetName(name) {
    return String(name || '').trim().toLocaleLowerCase();
}

/**
 * Finds a preset by its user-visible name, ignoring surrounding whitespace and case.
 * @param {Array<{id: string, name: string, data: any}>} presets
 * @param {unknown} name
 */
function findCharacterCreatorPresetByName(presets, name) {
    const normalized = normalizeCharacterCreatorPresetName(name);
    if (!normalized) return null;
    return (presets || []).find(preset => normalizeCharacterCreatorPresetName(preset?.name) === normalized) || null;
}

/**
 * Inserts a new preset or replaces the data of an existing same-name preset.
 * Existing IDs are retained so the selected preset remains stable after overwrite.
 * @param {Array<{id: string, name: string, data: any}>} presets
 * @param {string} name
 * @param {any} data
 * @param {() => string} createId
 */
function upsertCharacterCreatorPreset(presets, name, data, createId) {
    const trimmedName = String(name || '').trim();
    const existing = findCharacterCreatorPresetByName(presets, trimmedName);
    const preset = {
        id: existing?.id || createId(),
        name: trimmedName,
        data,
    };
    if (!existing) {
        return { presets: [...(presets || []), preset], preset, overwritten: false };
    }
    return {
        presets: (presets || []).map(item => item.id === existing.id ? preset : item),
        preset,
        overwritten: true,
    };
}

